  label?: string;
  /** Client-side arrival time of the "start" phase (live duration display). */
  client_started_at?: number;
  /** Client-side arrival time of the "end"/"error" phase. */
  client_ended_at?: number;
  /** OS sandbox backend a shell command runs in ("native", "bwrap"); absent when unconfined. */
  sandbox?: string;
