/**
 * Backend-owned contract for how a slash command affects WebUI turn state.
 *
 * - side_channel: returns control text without starting or ending an agent turn.
 * - finalize_active_turn: side-channel command that also closes the active UI turn.
 * - stop_active_turn: cancels the active turn; exact submits may be intercepted locally.
 * - agent_turn: always enters the normal agent path.
 * - agent_turn_with_args: no args is side-channel usage; args enter the agent path.
 */
export type SlashCommandLifecycle =
  | "side_channel"
  | "finalize_active_turn"
  | "stop_active_turn"
  | "agent_turn"
  | "agent_turn_with_args";

export interface SlashCommand {
  command: string;
  title: string;
  description: string;
  icon: string;
  argHint?: string;
  lifecycle: SlashCommandLifecycle;
  acceptsArgs: boolean;
}

export type ConnectionStatus =
  | "idle"
  | "connecting"
  | "open"
  | "reconnecting"
  | "closed"
  | "error";

export interface InboundTurnMetadata {
  turn_id?: string;
  turn_phase?: UITurnPhase;
  turn_seq?: number;
  model_name?: string;
  model_label?: string;
  task_role?: string;
}

export type PresenceMember = {
  member_id: string;
  display_name: string;
  role: string;
};

export type InboundEvent =
  | {
      event: "ready";
      chat_id: string;
      client_id: string;
      org_role?: string;
      display_name?: string;
    }
  | { event: "attached"; chat_id: string }
  | {
      event: "presence_sync";
      chat_id: string;
      members: PresenceMember[];
    }
  | {
      event: "presence_join";
      chat_id: string;
      member: PresenceMember;
    }
  | {
      event: "presence_leave";
      chat_id: string;
      member: PresenceMember;
    }
  | {
      event: "member_cursor";
      chat_id: string;
      member_id?: string;
      display_name?: string;
      cursor?: Record<string, unknown>;
    }
  /** navin.live account changed gateway-side (sign-in handoff, plan change,
   * sign-out): consumers should refetch `/api/webui/account`. */
  | { event: "account_updated" }
  | ({
      event: "message";
      chat_id: string;
      text: string;
      reply_to?: string;
      media?: string[];
      media_urls?: Array<{ url: string; name?: string }>;
      tool_events?: ToolProgressEvent[];
      /** Present when the frame is an agent breadcrumb (e.g. tool hint,
       * generic progress line) rather than a conversational reply. */
      kind?: "tool_hint" | "progress" | "reasoning";
      /** Server-measured turn wall time when this frame finishes an assistant reply. */
      latency_ms?: number;
      /** Model that produced this assistant frame. */
      model_name?: string;
      model_label?: string;
      model_preset?: string;
      task_role?: string;
      /** Lightweight provenance for proactive assistant messages. */
      source?: UIMessageSource;
      /** Optional structured payload on progress frames (channel-specific). */
      agent_ui?: AgentUIBlob;
    } & InboundTurnMetadata)
  | ({
      event: "file_edit";
      chat_id: string;
      edits: UIFileEdit[];
    } & InboundTurnMetadata)
  | {
      /** Coalesced gateway watcher signal: files changed on disk under root. */
      event: "fs_changed";
      chat_id: string;
      root: string;
    }
  | ({
      event: "delta";
      chat_id: string;
      text: string;
      stream_id?: string;
    } & InboundTurnMetadata)
  | ({
      event: "stream_end";
      chat_id: string;
      stream_id?: string;
      text?: string;
    } & InboundTurnMetadata)
  | ({
      event: "reasoning_delta";
      chat_id: string;
      text: string;
      stream_id?: string;
    } & InboundTurnMetadata)
  | ({
      event: "reasoning_end";
      chat_id: string;
      stream_id?: string;
    } & InboundTurnMetadata)
  | {
      event: "runtime_model_updated";
      model_name: string;
      model_preset?: string | null;
      reason?: string | null;
      previous_model?: string | null;
      used_percent?: number | null;
    }
  | ({
      event: "turn_end";
      chat_id: string;
      latency_ms?: number;
      /** Wall time per agent turn phase (restore/build/run/save...), in ms. */
      phase_timings_ms?: Record<string, number>;
      /** Model that finished this turn (keeps history labels stable). */
      model_name?: string;
      model_label?: string;
      model_preset?: string;
      task_role?: string;
      /** Authoritative sustained-goal snapshot for this chat (same shape as ``goal_state`` events). */
      goal_state?: GoalStateWsPayload;
    } & InboundTurnMetadata)
  | {
      event: "goal_status";
      chat_id: string;
      /** Turn executing (user message through agent loop). */
      status: "running" | "idle";
      /** Server ``time.time()`` when ``status`` is ``running``. */
      started_at?: number;
    }
  | {
      event: "goal_state";
      chat_id: string;
      goal_state: GoalStateWsPayload;
    }
  | {
      event: "session_updated";
      chat_id: string;
      scope?: "metadata" | "thread" | string;
      workspace_scope?: WorkspaceScopePayload;
    }
  | { event: "board_updated"; project_path?: string }
  | {
      event: "montage_updated";
      project_path?: string;
      kind?: "timeline" | "job" | "assets" | string;
      name?: string;
      job?: import("./api").MontageJobSummary;
    }
  | {
      event: "metagraph_updated";
      project_path?: string;
      generation?: number;
      view?: string;
      diff?: MetagraphDiff;
    }
  | {
      event: "notification";
      chat_id?: string;
      title: string;
      detail?: string;
      level?: "info" | "success" | "warning" | "error" | string;
      source?: string;
      key?: string;
    }
  | {
      event: "context_compacted";
      chat_id: string;
      /** "consolidation" = token pressure mid-conversation, "idle" = auto-compact. */
      kind: "consolidation" | "idle" | string;
      messages_archived?: number;
      tokens_before?: number;
      tokens_after?: number;
    }
  | {
      /** A restore point (conversation + code) was snapshotted for this turn. */
      event: "checkpoint_saved";
      chat_id: string;
      name: string;
      auto?: boolean;
    }
  | {
      /** A tool has suspended itself and is waiting for an answer. */
      event: "approval_request";
      chat_id: string;
      request_id: string;
      tool: string;
      action: string;
      reason: string;
      detail?: string;
      consequence?: string;
      scope?: string;
      remember_offered?: boolean;
      /** Epoch ms after which the backend refuses by itself. */
      expires_at_ms?: number | null;
    }
  | {
      /** A pending request is settled, however it ended. */
      event: "approval_closed";
      chat_id: string;
      request_id: string;
      allowed: boolean;
      reason?: string;
    }
  | {
      /** The agent paused on a product fork and is waiting for a pick. */
      event: "choice_request";
      chat_id: string;
      request_id: string;
      question: string;
      options: Array<{
        id: string;
        label: string;
        detail?: string;
        recommended?: boolean;
      }>;
      allow_skip?: boolean;
      recommended_id?: string;
      expires_at_ms?: number | null;
    }
  | {
      event: "choice_closed";
      chat_id: string;
      request_id: string;
      option_id?: string;
      skipped?: boolean;
    }
  | {
      event: "terminal_open_request";
      chat_id?: string;
      shell?: string;
      cwd?: string;
    }
  | {
      /** Live feed of an agent exec command (read-only terminal tabs). */
      event: "agent_exec";
      chat_id?: string;
      id?: string;
      phase?: string;
      command?: string;
      cwd?: string;
      background?: boolean;
      data?: string;
      exit_code?: number;
    }
  | {
      /** Live mirror of the agent's headless browser (screencast frames). */
      event: "agent_browser";
      chat_id?: string;
      id?: string;
      phase?: string;
      url?: string;
      title?: string;
      action?: string;
      data?: string;
      width?: number;
      height?: number;
      user_control?: boolean;
    }
  | {
      event: "agent_browser_input_done" | "agent_browser_closed" | "agent_browser_error";
      chat_id?: string;
      id?: string;
      request_id?: string;
      user_control?: boolean;
      url?: string;
      closed?: boolean;
      detail?: string;
    }
  | {
      event: "editor_open_request";
      chat_id?: string;
      path?: string;
      kind?: string;
      line?: number;
    }
  | {
      event: "composer_mode_request";
      chat_id?: string;
      mode?: string;
    }
  | {
      /** Open a product module surface (Code workbench, …) for this turn. */
      event: "product_module_request";
      chat_id?: string;
      module?: string;
    }
  | {
      /** Live parallel subagent card (spawn fan-out). */
      event: "subagent_progress";
      chat_id?: string;
      task_id: string;
      label: string;
      phase: string;
      status_line: string;
      model?: string;
      iteration?: number;
      done?: boolean;
      error?: string;
      task_description?: string;
    }
  | {
      event: "preview_open_request";
      chat_id?: string;
      kind?: "web" | "mobile" | string;
      url?: string;
    }
  | {
      event: "file_preview_open_request";
      chat_id?: string;
      path?: string;
    }
  | {
      event: "artifact_upsert";
      chat_id?: string;
      artifact?: ArtifactRecord;
    }
  | {
      event: "artifact_select";
      chat_id?: string;
      artifact_id?: string;
    }
  | { event: "terminal_shells"; shells: TerminalShellInfo[] }
  | { event: "terminal_opened"; terminal_id: string; shell?: string; cwd?: string }
  | { event: "terminal_output"; terminal_id: string; data: string }
  | { event: "terminal_exit"; terminal_id: string; exit_code?: number | null }
  | { event: "terminal_error"; terminal_id?: string; detail?: string }
  | { event: "assist_delta"; request_id: string; text?: string }
  | {
      event: "assist_done";
      request_id: string;
      completion?: string;
      replacement?: string;
      model?: string;
      reason?: string;
      cancelled?: boolean;
      route?: string;
      latency_ms?: number;
      ttft_ms?: number;
    }
  | { event: "assist_error"; request_id?: string; detail?: string; status?: number }
  | {
      event: "mobile_preview_opened";
      preview_id: string;
      serial?: string | null;
      backend?: string;
    }
  | {
      event: "mobile_preview_frame";
      preview_id: string;
      png_b64?: string;
      width?: number;
      height?: number;
      seq?: number;
      ts_ms?: number;
      fps?: number;
      mem_mb?: number;
      cpu_pct?: number;
      error?: string;
    }
  | {
      event: "mobile_preview_logs";
      preview_id: string;
      lines?: string[];
    }
  | {
      event: "mobile_preview_ui_dump";
      preview_id: string;
      xml?: string;
    }
  | {
      event: "mobile_preview_error";
      preview_id?: string;
      detail?: string;
    }
  | { event: "mobile_preview_exit"; preview_id: string }
  | {
      event: "mobile_preview_status";
      ready?: boolean;
      adb?: string | null;
      sdk?: string | null;
      source?: string | null;
      devices?: string[];
      avds?: string[];
      error?: string | null;
      help?: string | null;
      fixes?: MobilePreviewFix[];
    }
  | { event: "mobile_preview_avd_started"; ok?: boolean; detail?: string | null }
  | { event: "transcription_result"; request_id: string; text: string }
  | {
      event: "transcription_error";
      request_id?: string;
      detail?: string;
      provider?: string;
    }
  | {
      event: "voice_session_started";
      session_id: string;
      request_id?: string;
      auto_speak?: boolean;
      tts_provider?: string;
      tts_configured?: boolean;
      voice?: string;
    }
  | {
      event: "voice_session_ended";
      session_id: string;
      request_id?: string;
    }
  | {
      event: "transcript_partial";
      session_id: string;
      text: string;
      final?: boolean;
      request_id?: string;
    }
  | {
      /** Live conversation: the spoken transcript rewritten as the chat prompt. */
      event: "voice_prompt_ready";
      session_id: string;
      text: string;
      raw_text: string;
      rewritten?: boolean;
      request_id?: string;
    }
  | {
      event: "tts_audio";
      session_id: string;
      audio_base64: string;
      mime?: string;
      request_id?: string;
    }
  | {
      event: "tts_cancelled";
      session_id: string;
      request_id?: string;
    }
  | {
      event: "voice_session_error";
      detail?: string;
      session_id?: string;
      request_id?: string;
      provider?: string;
      required_plans?: string[];
    }
  | {
      event: "error";
      chat_id?: string;
      detail?: string;
      reason?: string;
    };

/** Base64-encoded file attached to an outbound ``message`` envelope.
 *
 * ``data_url`` must use a server-whitelisted image, video, or document MIME
 * type. SVG remains rejected on ingress to avoid an embedded-script XSS
 * surface. ``name`` is advisory and is surfaced as the placeholder label when
 * the session is replayed.
 */
export interface OutboundMedia {
  data_url: string;
  name?: string;
}

export interface OutboundCliAppMention {
  name: string;
  display_name?: string;
  category?: string;
  entry_point?: string;
  logo_url?: string | null;
  brand_color?: string | null;
}

export interface OutboundMcpPresetMention {
  name: string;
  display_name?: string;
  category?: string;
  transport?: string;
  status?: string;
  configured?: boolean;
  logo_url?: string | null;
  brand_color?: string | null;
}

/** A workspace path the user attached with `@path`, scoping the turn. */
export interface OutboundFileMention {
  path: string;
  kind: "file" | "directory" | "symbol";
  /** Identifier for a symbol mention; the file's own name is derived server-side. */
  name?: string;
  /** 1-based definition line for a symbol mention. */
  line?: number;
}

/** Response shape for ``GET .../webui-thread`` (server-built transcript replay). */
export interface WebuiThreadPagePayload {
  before_cursor?: string | null;
  has_more_before?: boolean;
  loaded_message_count?: number;
  total_known_message_count?: number;
  user_message_offset?: number;
}

export interface WebuiThreadPersistedPayload {
  schemaVersion: number;
  sessionKey?: string;
  savedAt?: string;
  messages: UIMessage[];
  fork_boundary_message_count?: number;
  has_pending_tool_calls?: boolean;
  page?: WebuiThreadPagePayload;
  workspace_scope?: WorkspaceScopePayload;
}

export type FilePreviewKind =
  | "text"
  | "image"
  | "binary"
  | "audio"
  | "video"
  | "pdf"
  | "office"
  | "spreadsheet"
  | "csv"
  | "html"
  | "markdown"
  | "json"
  | "xml"
  | "yaml";

/** One worksheet of an Excel file, as text cells for the table viewer. */
export interface SpreadsheetSheetPayload {
  name: string;
  rows: string[][];
  /** More rows or columns exist than the gateway sends. */
  truncated?: boolean;
  hidden?: boolean;
}

/** Artifact shown in the chat-side Artifact Canvas (HTML / MD / Mermaid / file). */
export type ArtifactType = "html" | "markdown" | "mermaid" | "file";

export interface ArtifactRecord {
  id: string;
  chat_id?: string;
  type: ArtifactType | string;
  title: string;
  content?: string;
  version?: number;
  created_at?: string;
  updated_at?: string;
  source_path?: string | null;
  content_file?: string;
}

export interface FilePreviewPayload {
  path: string;
  display_path: string;
  project_path: string;
  language: string;
  content: string;
  size: number;
  truncated: boolean;
  kind?: FilePreviewKind;
  data_url?: string;
  name?: string;
  mime?: string;
  /** Office files: whether the gateway can render them to PDF (LibreOffice). */
  render_available?: boolean;
  /** Office files: how to install the renderer when it is missing. */
  render_hint?: string;
  /** kind=spreadsheet: worksheets read natively by the gateway (no LibreOffice). */
  sheets?: SpreadsheetSheetPayload[];
}

export interface FileSavePayload {
  path: string;
  display_path: string;
  size: number;
  saved: boolean;
}

export interface FileCreatePayload {
  path: string;
  display_path: string;
  kind: "file" | "directory";
  created: boolean;
}

export interface FileDeletePayload {
  path: string;
  display_path: string;
  kind: "file" | "directory";
  deleted: boolean;
}

export interface FileRenamePayload {
  path: string;
  display_path: string;
  previous_path?: string;
  renamed: boolean;
}

export interface FilePastePayload {
  path: string;
  display_path: string;
  kind: "file" | "directory";
  /** Set only for a move, so callers know which path stopped existing. */
  previous_path?: string | null;
  pasted: boolean;
}

export interface FileTreeEntry {
  name: string;
  path: string;
  type: "dir" | "file";
  size: number;
  heavy?: boolean;
}

export interface FileTreePayload {
  path: string;
  display_path: string;
  project_path: string;
  entries: FileTreeEntry[];
  truncated: boolean;
}

export interface TerminalShellInfo {
  name: string;
  path: string;
  default: boolean;
  kind?: string;
}

export interface TerminalEvent {
  event: "terminal_opened" | "terminal_output" | "terminal_exit" | "terminal_error";
  terminal_id: string;
  shell?: string;
  cwd?: string;
  data?: string;
  exit_code?: number | null;
  detail?: string;
  /** On terminal_opened: the shell actually runs inside the OS sandbox. */
  sandbox?: boolean;
}

export interface MobilePreviewFix {
  id: string;
  label: string;
  command?: string;
  prompt?: string;
}

export interface MobileGuideStep {
  id: number;
  key: string;
  title: string;
  body: string;
  status: "done" | "current" | "todo";
  primary_action?: string | null;
  primary_label?: string | null;
  secondary_action?: string | null;
  secondary_label?: string | null;
  link?: string | null;
  link_label?: string | null;
}

export interface MobileGuide {
  current_step: number;
  headline: string;
  subtitle: string;
  steps: MobileGuideStep[];
}

export interface MobilePreviewIosChainStep {
  id: string;
  title: string;
  ok: boolean;
  required?: boolean;
  detail?: string;
  command?: string;
  verify?: string;
  role?: string;
}

export interface MobilePreviewIosStatus {
  available?: boolean;
  supported?: boolean;
  ready?: boolean;
  platform?: string | null;
  reason?: string | null;
  help?: string | null;
  error?: string | null;
  xcode?: boolean;
  simctl?: boolean;
  idevice?: boolean;
  idb?: boolean;
  brew?: boolean;
  devices?: string[];
  simulators?: Array<{ udid: string; name: string; state: string }>;
  usb_devices?: string[];
  /** Ordered install/verify chain for iOS on this host. */
  chain?: MobilePreviewIosChainStep[];
  fixes?: MobilePreviewFix[];
}

export interface MobilePreviewStatus {
  ready: boolean;
  platform?: string | null;
  /** Stacks available on this host, e.g. ["android"] or ["android","ios"]. */
  stacks?: string[];
  adb?: string | null;
  sdk?: string | null;
  source?: string | null;
  devices: string[];
  /** Plugged phones not usable yet (unauthorized RSA prompt, offline...). */
  pending_devices?: string[];
  avds: string[];
  error?: string | null;
  help?: string | null;
  fixes: MobilePreviewFix[];
  can_auto_install?: boolean;
  acceleration_ok?: boolean;
  acceleration_detail?: string | null;
  stable?: boolean;
  block_local_emulator?: boolean;
  recommendations?: string[];
  guide?: MobileGuide | null;
  ios?: MobilePreviewIosStatus | null;
  install_attempt?: {
    ok?: boolean;
    already?: boolean;
    adb?: string;
    detail?: string;
    help?: string;
    log?: string;
  } | null;
}

export type MobilePreviewEvent =
  | {
      event: "mobile_preview_opened";
      preview_id: string;
      serial?: string | null;
      backend?: string;
    }
  | {
      event: "mobile_preview_frame";
      preview_id: string;
      png_b64?: string;
      width?: number;
      height?: number;
      seq?: number;
      ts_ms?: number;
      fps?: number;
      mem_mb?: number;
      cpu_pct?: number;
      error?: string;
    }
  | {
      event: "mobile_preview_logs";
      preview_id: string;
      lines?: string[];
    }
  | {
      event: "mobile_preview_ui_dump";
      preview_id: string;
      xml?: string;
    }
  | {
      event: "mobile_preview_error";
      preview_id?: string;
      detail?: string;
    }
  | {
      event: "mobile_preview_exit";
      preview_id: string;
    }
  | ({
      event: "mobile_preview_status";
    } & MobilePreviewStatus);

export type Outbound =
  | { type: "new_chat"; workspace_scope?: WorkspaceScopePayload }
  | { type: "fork_chat"; source_chat_id: string; before_user_index: number; title?: string }
  | { type: "attach"; chat_id: string }
  | { type: "set_workspace_scope"; chat_id: string; workspace_scope: WorkspaceScopePayload }
  | { type: "transcribe_audio"; request_id: string; data_url: string; duration_ms?: number }
  | {
      type: "voice_session_start";
      request_id: string;
      session_id?: string;
    }
  | {
      type: "voice_audio_chunk";
      request_id: string;
      session_id: string;
      data_url?: string;
      duration_ms?: number;
      final?: boolean;
      speak_text?: string;
      barge_in?: boolean;
      cancel_tts?: boolean;
    }
  | {
      type: "voice_prompt";
      request_id: string;
      session_id: string;
      text: string;
      context?: string;
    }
  | {
      type: "voice_session_end";
      request_id: string;
      session_id: string;
      speak_text?: string;
      barge_in?: boolean;
      cancel_tts?: boolean;
    }
  | { type: "approval_decision"; request_id: string; allowed: boolean; remember: boolean }
  | { type: "choice_answer"; request_id: string; option_id?: string; skipped?: boolean; custom_text?: string }
  | { type: "terminal_shells" }
  | {
      type: "terminal_open";
      terminal_id: string;
      shell?: string;
      chat_id?: string;
      cols?: number;
      rows?: number;
      cwd?: string;
      /** Isolated terminal: start the shell inside the agent's OS sandbox. */
      sandbox?: boolean;
    }
  | { type: "terminal_input"; terminal_id: string; data: string }
  | { type: "terminal_resize"; terminal_id: string; cols: number; rows: number }
  | { type: "terminal_close"; terminal_id: string }
  | {
      type: "mobile_preview_open";
      preview_id: string;
      serial?: string;
      fps?: number;
    }
  | { type: "mobile_preview_close"; preview_id: string }
  | { type: "mobile_preview_status"; install?: boolean }
  | { type: "mobile_preview_start_avd"; avd: string }
  | { type: "mobile_preview_tap"; preview_id: string; x: number; y: number }
  | {
      type: "mobile_preview_swipe";
      preview_id: string;
      x1: number;
      y1: number;
      x2: number;
      y2: number;
      duration_ms?: number;
    }
  | { type: "mobile_preview_key"; preview_id: string; keycode: string }
  | { type: "mobile_preview_text"; preview_id: string; text: string }
  | { type: "mobile_preview_ui_dump"; preview_id: string }
  | {
      /** A click or keystroke the user made on the mirror of the agent's browser. */
      type: "agent_browser_input";
      chat_id: string;
      id?: string;
      request_id?: string;
      action: "click" | "move" | "scroll" | "text" | "key" | "takeover" | "release";
      /** Point on the streamed frame, in that frame's own pixels. */
      x?: number;
      y?: number;
      /** Size of the frame the point was measured against. */
      width?: number;
      height?: number;
      dx?: number;
      dy?: number;
      text?: string;
      key?: string;
      count?: number;
      button?: "left" | "right" | "middle";
    }
  | { type: "agent_browser_close"; chat_id: string; id?: string; request_id?: string }
  | {
      type: "assist_complete";
      request_id: string;
      path: string;
      prefix: string;
      suffix: string;
      language?: string;
    }
  | {
      type: "assist_edit";
      request_id: string;
      path: string;
      selection: string;
      instruction: string;
      prefix?: string;
      suffix?: string;
      language?: string;
    }
  | { type: "assist_cancel"; request_id: string }
  | {
      type: "message";
      chat_id: string;
      content: string;
      media?: OutboundMedia[];
      cli_apps?: OutboundCliAppMention[];
      mcp_presets?: OutboundMcpPresetMention[];
      file_mentions?: OutboundFileMention[];
      document_template?: { category: string; name: string };
      media_template?: { id: string; title?: string };
      media_templates?: { id: string; title?: string }[];
      workspace_scope?: WorkspaceScopePayload;
      turn_id?: string;
      /** Model preset pinned to this conversation; shapes this turn only and
       * leaves the global default untouched. */
      model_preset?: string;
      /** Product shell module (code, seo, …) for tool/skill scoping. */
      product_module?: string;
      /** Open editor tabs from the Code workbench (agent context pack). */
      open_files?: string[];
      /** Sent from the live voice conversation: the reply is read aloud, so
       * the agent talks like a colleague on a call. */
      voice_mode?: true;
      /** Marks messages sent by the embedded WebUI, without changing the
       * generic websocket protocol for other clients. */
      webui?: true;
    };
